contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a hash and an amount to send when locking; amount must be exactly 1 ether
    function run(bytes32 hash, uint256 amount) public payable {
        // ensure this contract has enough balance to send amount
        require(address(this).balance >= amount);
        // record balances before
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        // call lockInGuess with provided amount; must be a top-level statement
        try c.lockInGuess{value: amount}(hash) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read the stored Guess for this contract via the public getter
        // The auto-generated getter for mapping(address=>Guess) guesses takes an address and returns (uint256, bytes32)
        (uint256 recordedBlock, bytes32 recordedHash) = c.guesses(address(this));

        // Assertion: If the call did NOT revert then amount must have been exactly 1 ether,
        // the contract's stored block must be non-zero and strictly greater than current block (it sets block.number+1)
        // and the stored hash must equal the provided hash, and c's balance increased by amount while this contract's balance decreased by >= amount.
        // We use >= for this contract's balance decrease because gas may be spent.
        assert(
            reverted || (
                amount == 1 ether &&
                recordedBlock != 0 &&
                // recordedBlock should be at least current block + 1. We can only observe block.number; require recordedBlock > block.number - 0
                // because lockInGuess sets block.number + 1, and the call occurred in this same transaction, so recordedBlock > block.number is not guaranteed here
                // Instead assert recordedBlock > 0 (nonzero future indicator) and recordedHash equals provided hash
                recordedHash == hash &&
                address(c).balance == beforeC + amount &&
                address(this).balance <= beforeThis - amount + 1 wei // allow 1 wei slack for gas accounting in different EVMs
            )
        );
    }

    receive() external payable {}
}

