        require(address(this).balance >= amount);

        // record balances before the call
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        // top-level state-changing call to c
        try c.lockInGuess{value: amount}(hash) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule: if the call reverted then balances are unchanged; otherwise c gained exactly 1 ether
        // and this contract's balance decreased by at least 1 ether (gas may add extra decrease)
        assert(
            (reverted && afterC == beforeC && afterThis == beforeThis)
            || (
                !reverted
                && afterC == beforeC + 1 ether
                && beforeThis >= afterThis + 1 ether
            )
        );
    }

    // allow receiving Ether
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: 1) lock in a guess (if possible) by sending exactly 1 ether; 2) advance to a later block by doing a no-op call pattern
    // but since we cannot mine blocks in the checker, we instead attempt to call settle() and observe behavior.
    // Inputs: a hash to lock, and an amount to send when locking (we require it's 1 ether so lockInGuess can succeed).
    function run(bytes32 hash, uint256 amount) public payable {
        // ensure the test contract has enough balance to send 'amount'
        require(address(this).balance >= amount);

        // Precondition on amount so lockInGuess can succeed when invoked: it requires msg.value == 1 ether
        // Allow the test to try both value==1 ether and other values (which will cause lockInGuess to revert).
        // Record balances before any operations
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // First: try to lock in a guess. This may revert; capture that.
        bool lockReverted;
        try c.lockInGuess{value: amount}(hash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // After attempting lock, read the public getter for guesses mapping via the auto-generated accessor.
        // The mapping is not public in C, so there is no getter; therefore we can only observe via behavior (settle outcome)
        // Now attempt to call settle(); it may revert. Capture revert and balances after.
        bool settleReverted;
        uint256 midC = address(c).balance;
        uint256 midThis = address(this).balance;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }
        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule asserted:
        // If settle() succeeded (did not revert) then the stored block number for this tester must have been cleared to 0.
        // We cannot directly read the internal mapping, so we express an observable equivalent: after a successful settle,
        // a subsequent call to lockInGuess must be allowed (i.e., not revert for the reason guesses[msg.sender].block==0)
        // when sending exactly 1 ether. Therefore we check: if settle succeeded, then calling lockInGuess{value:1 ether}(0x0)
        // must not revert (we detect this by trying it). We also assert that when settle succeeded, either c paid out 2 ether
        // (tester balance increased by at least 2 ether) or c did not payout (tester balance did not increase by 2 ether) —
        // this distinguishes the two allowed outcomes based on guess equality.

        bool postLockReverted;
        // ensure we have at least 1 ether to attempt locking again
        if (address(this).balance >= 1 ether) {
            try c.lockInGuess{value: 1 ether}(bytes32(0)) {
                postLockReverted = false;
            } catch {
                postLockReverted = true;
            }
        } else {
            // If we lack funds to retest lock, treat as reverted (conservative)
            postLockReverted = true;
        }

        // Now assert the general rule in a single assert expression:
        // If settle did not revert then: postLockReverted must be false (block cleared) AND
        // either tester gained at least 2 ether compared to midThis (indicating payout) OR c's balance did not decrease by 2 ether.
        // We express "tester gained at least 2 ether" as afterThis >= midThis + 2 ether.
        // And "c's balance did not decrease by 2 ether" as afterC + 2 ether >= midC.

        assert(
            // If settle reverted, we make no claim (always allow)
            (settleReverted)
            || (
                // settle succeeded: lock slot should be cleared so re-locking with 1 ether must succeed
                (!settleReverted && postLockReverted == false)
                && (
                    // either tester was paid out >=2 ether
                    (afterThis >= midThis + 2 ether)
                    // or c did not lose exactly 2 ether (i.e., did not transfer 2 ether to tester)
                    || (afterC + 2 ether >= midC)
                )
            )
        );
    }

    // Allow receiving Ether
    receive() external payable {}
}

