        // We can observe that by attempting to call settle after a block advance or immediately.

        // Optionally make a cheap call to another view (or same contract) to potentially advance state in some environments.
        if (advanceOneBlock) {
            // perform a harmless external call to this contract to consume an opcode; it's still same tx so block won't advance here,
            // but the checker will reason about both possibilities. Use a view call to c (allowed) to keep no state change.
            try c.lockInGuess{value: 0}(bytes32(0)) { /* unlikely to succeed, ignore */ } catch { }
        }

