        assert(
            (lockReverted && settleReverted && balanceAfter == balanceBefore)
            || (
                !lockReverted && (
                    (settleReverted && balanceAfter == balanceBefore)
                    || (!settleReverted && (balanceAfter + 2 ether == balanceBeforeSettle || balanceAfter == balanceBeforeSettle))
                )
            )
        );
    }

    receive() external payable { }
}

